cfg, err := LoadConfig(*configPath)
if err != nil {
	return err
}
if len(forwards) != 0 {
	if cfg.NATS.ClientRole != "operator" {
		return errors.New("NATS forwarding requires the operator role config")
	}
	cfg.NATS.OperatorForward = forwards
