func netbirdManagementLoop(control authority.Fencer) manager.Loop {
	return manager.Automatic(control, func(ctx context.Context) (vaultsecret.Ref, error) {
		local, err := foundationDiscovery(ctx)
		if err != nil {
			return vaultsecret.Ref{}, err
		}
		foundation, err := local.foundations.Resolve(ctx, "GRU")
		if err != nil {
			return vaultsecret.Ref{}, err
		}
		target, err := foundation.VaultTarget()
		if err != nil {
			return vaultsecret.Ref{}, err
		}
		return vaultsecret.Ref{Vault: target.VaultID, Name: "gru-1-netbird-admin-pat"}, nil
	}, log.Printf)
}

func Automatic(fencer authority.Fencer, credential func(context.Context) (vaultsecret.Ref, error),
	logf func(string, ...any),
) Loop {
	return Loop{Authority: fencer, Desired: GRU(), Logf: logf, Token: func(ctx context.Context) ([]byte, error) {
		if credential == nil {
			return nil, errors.New("NetBird management pending GRU foundation")
		}
		ref, err := credential(ctx)
		if err != nil {
			return nil, errors.New("NetBird management pending GRU foundation credential")
		}
		if ref.Name != "gru-1-netbird-admin-pat" || !strings.HasPrefix(ref.Vault, "ocid1.vault.oc1.sa-saopaulo-1.") {
			return nil, errors.New("NetBird management credential does not belong to the GRU foundation")
		}
		values, err := vaultsecret.ReadCurrentRefs(ctx, map[string]vaultsecret.Ref{"NETBIRD_ADMIN_PAT": ref})
		if err != nil {
			return nil, errors.New("NetBird management pending GRU Vault credential")
		}
		token := []byte(values["NETBIRD_ADMIN_PAT"].Value())
		if !netbird.ValidAdminPAT(token) {
			clear(token)
			return nil, errors.New("NetBird management Vault credential has an invalid shape")
		}
		return token, nil
	}}
}

func (l Loop) withDefaults() Loop {
	if l.Interval <= 0 {
		l.Interval = defaultLoopInterval
	}
	if l.ManagementURL == "" {
		l.ManagementURL = DefaultManagementURL
	}
	if l.newAPI == nil {
		l.newAPI = NewAPI
	}
	// A loop without a leadership check must never mutate the manager, so a
	// nil Leader means "not the leader" rather than "always lead": every
	// controller of a cell would otherwise reconcile concurrently.
	if l.Leader == nil {
		l.Leader = func() bool { return false }
	}
	if l.Logf == nil {
		l.Logf = func(string, ...any) {}
	}
	return l
}

// Run reconciles until ctx ends.
func (l Loop) Run(ctx context.Context) {
	l = l.withDefaults()
	// Let the controller settle before the first cycle.
	delay := l.initialDelay
	if delay <= 0 {
		delay = jitter(30 * time.Second)
	}
	retry := firstRetry
	warned := map[string]bool{}
	for {
		ctx := observability.StartTrace(ctx)
		timer := time.NewTimer(delay)
		select {
		case <-ctx.Done():
			timer.Stop()
			return
		case <-timer.C:
		}
		if !l.leading() {
			delay, retry = jitter(l.Interval), firstRetry
			continue
		}
		if err := l.cycle(ctx, warned); err != nil {
			if ctx.Err() != nil {
				return
			}
			l.Logf("NetBird management failed, retrying in %s: %v", retry, err)
			delay, retry = jitter(retry), min(retry*2, maxRetry)
			continue
		}
		delay, retry = jitter(l.Interval), firstRetry
	}
}

func foundationDiscovery(ctx context.Context) (automaticFoundation, error) {
	imds := bootstrapstart.NewIMDSClient()
	instanceID, err := imds.FetchInstanceID(ctx)
	if err != nil {
		return automaticFoundation{}, fmt.Errorf("discover local OCI instance identity: %w", err)
	}
	parts := strings.Split(instanceID, ".")
	if len(parts) != 5 {
		return automaticFoundation{}, bootstrapstart.ErrInstanceObservation
	}
	entry, ok := catalog.CellForOCIRegion(parts[3])
	if !ok {
		return automaticFoundation{}, errors.New("local OCI instance region is outside the region catalog")
	}
	baked, err := bootstrapstart.LoadBakedInputs()
	if err != nil {
		return automaticFoundation{}, err

func NewIMDSClient() IMDSClient {
	dialer := &net.Dialer{Timeout: imdsTimeout}
	transport := &http.Transport{
		Proxy: nil, DisableKeepAlives: true, ResponseHeaderTimeout: imdsTimeout,
		DialContext: func(ctx context.Context, network, address string) (net.Conn, error) {
			if network != "tcp" || address != imdsAddress {
				return nil, ErrInvalidDescriptor
			}
			return dialer.DialContext(ctx, network, imdsAddress)
		},
	}
	return IMDSClient{client: &http.Client{
		Timeout: imdsTimeout, Transport: transport,
		CheckRedirect: func(*http.Request, []*http.Request) error { return ErrInvalidDescriptor },
	}}
}

func (imds IMDSClient) FetchDescriptor(ctx context.Context) (Descriptor, error) {
	data, err := imds.fetch(ctx, descriptorEndpoint, maxDescriptorBytes)
	if err != nil {
		return Descriptor{}, err
	}
	return ParseDescriptor(data)
}

// FetchInstanceID identifies the local VM from the fixed OCI IMDS endpoint.
// A caller must still compare it with authenticated OCI GetInstance/VNIC facts.
func (imds IMDSClient) FetchInstanceID(ctx context.Context) (string, error) {
	data, err := imds.fetch(ctx, identityEndpoint, 255)
	if err != nil {
		return "", err
	}
	id := strings.TrimSpace(string(data))
	if !instanceIDRE.MatchString(id) || !bytes.Equal(bytes.TrimSpace(data), []byte(id)) {
		return "", ErrInvalidDescriptor
	}
	return id, nil
}

func (imds IMDSClient) fetch(ctx context.Context, endpoint string, maximum int64) ([]byte, error) {
	if imds.client == nil || endpoint != descriptorEndpoint && endpoint != identityEndpoint &&
		endpoint != controllerManifestEndpoint && endpoint != identityMetadataEndpoint &&
		endpoint != anchorMetadataEndpoint && endpoint != hostEnrollmentMetadataEndpoint &&
		endpoint != operatorSSHKeyMetadataEndpoint && endpoint != availabilityDomainEndpoint &&
		endpoint != managedHostImageReceiptMetadataEndpoint && endpoint != managedHostImageDelegationMetadataEndpoint &&
		endpoint != faultDomainEndpoint {
		return nil, ErrInvalidDescriptor
	}
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return nil, err
	}
	request.Header.Set("Authorization", "Bearer Oracle")
	response, err := imds.client.Do(request)
	if err != nil {
		return nil, fmt.Errorf("read fixed OCI IMDS endpoint: %w", err)
	}
	defer response.Body.Close()
	if response.StatusCode == http.StatusNotFound {
		return nil, errMetadataAbsent
	}
	if response.StatusCode != http.StatusOK || response.ContentLength > maximum {
		return nil, ErrInvalidDescriptor
	}
	data, err := io.ReadAll(io.LimitReader(response.Body, maximum+1))
	if err != nil || len(data) == 0 || int64(len(data)) > maximum {
		return nil, ErrInvalidDescriptor
	}
	return data, nil
}

