func TestReleaseChannelInventoryHeartbeat(t *testing.T) {
	f := newChannelFixture(t)
	ctx := t.Context()
	now := time.Now().UTC()
	old := now.Add(-2 * releasechannel.PinRefreshInterval)
	consume := func(at time.Time) {
