	// signs and writes straight into the store is not adopted.
	if out, err := service(rotatedTrust.sign(t, root, set)); err != nil || !strings.Contains(out, `"status":"unchanged"`) {
		t.Fatalf("set under the new root: %v\n%s", err, out)
	}
