writeRotation := func(name string, signed trust.SignedRotation) string {
	wire, err := protocol.EncodeJSON(signed)
	if err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(root, name)
	if err := os.WriteFile(path, wire, 0o600); err != nil {
