	Services: []cellspec.Service{{Role: "web", Profile: WorkloadProfile{Resources: resources}}}}

chainFile := filepath.Join(root, "chain-0.json")
if got := roots(); got.Sequence != 0 {
	t.Fatalf("genesis %+v", got)
