if err != nil {
	t.Fatal(err)
}
forkWire, err := trust.EncodeRootChain(trust.RootChain{Version: 1, Rotations: []trust.SignedRotation{
	signTestRotation(t, id, base, rootKeys(attacker), genesisTrust.root, attacker)}})
if err != nil {
	t.Fatal(err)
