		t.Fatalf("object after deletion: %v", err)
	}
	if err := artifact.Touch(t.Context(), legacy, "ARTIFACTS", "object"); !errors.Is(err, jetstream.ErrObjectNotFound) {
		t.Fatalf("touch after deletion = %v, want ErrObjectNotFound", err)
