		t.Fatal(err)
	}
	if err := tsauth.ValidateMembers(profile.Env, a.profileEnv(a.Path("services", "terrabase.profile.json"))); err != nil {
		t.Fatal(err)
	}
	// The controllers colocate ts-auth; the database hosts run TerraBase and
