					_ = json.Unmarshal(data, &fields)
					if mode == "missing" {
						delete(fields, key)
					} else {
						fields[key] = json.RawMessage(`null`)
					}
					invalid, err := json.Marshal(fields)
					if err != nil {
						t.Fatal(err)
					}
					if err := json.Unmarshal(invalid, &parsed); err == nil {
						t.Fatalf("missing evidence accepted: %s", invalid)
					}
				})
			}
		}
	}
}

