func TestUsageAlignsWithCommonClientMeasurementWindow(t *testing.T) {
	for _, offset := range []int{4, 35} {
		t.Run((time.Duration(offset) * time.Second).String(), func(t *testing.T) {
			w := workload(t)
			w.Warmup = 5
			base := time.Now().UTC().Add(-2 * time.Minute)
			now := base
