							sample.TS = start.Add(sample.TS.Sub(stage.MeasurementFrom[client]))
							now = maxTime(now, sample.TS)
						}
						if err := emit(sample); err != nil {
							return err
						}
					}
				}
				now = base.Add(110 * time.Second)
				return nil
