	fixture := newAdmissionFlowFixture(t)
	gate := fixture.gate
	wire := gate.Ledgers.(*countingLedgerOpener).state.ManifestRecord.Bytes
	baked := BakedInputs{Roots: gate.Roots, AnchorWire: gate.AnchorWire,
